// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Check whether the process is alive
	// (GET /livez)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// Browse Memories
	// (GET /memories)
	BrowseMemories(ctx context.Context, request BrowseMemoriesRequestObject) (BrowseMemoriesResponseObject, error)
	// Import one Blob and understand it
	// (POST /memories/import)
	ImportMemory(ctx context.Context, request ImportMemoryRequestObject) (ImportMemoryResponseObject, error)
	// Get Memory details
	// (GET /memories/{memoryId})
	GetMemory(ctx context.Context, request GetMemoryRequestObject) (GetMemoryResponseObject, error)
	// Download a Memory's immutable Blob
	// (GET /memories/{memoryId}/content)
	GetMemoryContent(ctx context.Context, request GetMemoryContentRequestObject) (GetMemoryContentResponseObject, error)
	// List processing logs for a Memory
	// (GET /memories/{memoryId}/logs)
	ListProcessingLogs(ctx context.Context, request ListProcessingLogsRequestObject) (ListProcessingLogsResponseObject, error)
	// Rebuild a Memory's understanding
	// (POST /memories/{memoryId}/rebuild)
	RebuildMemory(ctx context.Context, request RebuildMemoryRequestObject) (RebuildMemoryResponseObject, error)
	// List successful Understanding Runs
	// (GET /memories/{memoryId}/runs)
	ListUnderstandingRuns(ctx context.Context, request ListUnderstandingRunsRequestObject) (ListUnderstandingRunsResponseObject, error)
	// Get one Understanding Run
	// (GET /memories/{memoryId}/runs/{runId})
	GetUnderstandingRun(ctx context.Context, request GetUnderstandingRunRequestObject) (GetUnderstandingRunResponseObject, error)
	// List logs associated with an Understanding Run
	// (GET /memories/{memoryId}/runs/{runId}/logs)
	ListRunLogs(ctx context.Context, request ListRunLogsRequestObject) (ListRunLogsResponseObject, error)
	// Check whether the server can accept requests
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// Search Memories with a natural-language query
	// (POST /search)
	SearchMemories(ctx context.Context, request SearchMemoriesRequestObject) (SearchMemoriesResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

